"""Writhe lower bound on firing events.

A cognitive process with net directed charge c must contain at least |c|
elementary crossings, because each crossing changes the writhe by exactly +-1.
"""
from __future__ import annotations
from typing import List, Tuple

Letter = Tuple[int, bool]
BraidWord = List[Letter]


def writhe(word: BraidWord) -> int:
    return sum(1 if l[1] else -1 for l in word)


def min_crossings(net_charge: int) -> int:
    """Minimum number of elementary crossings to realize a given net charge."""
    return abs(net_charge)


if __name__ == "__main__":
    for word in ([(0, True)] * 5, [(0, True), (1, False), (2, True)]):
        c = writhe(word)
        print(f"word length {len(word)}, writhe {c}, floor {min_crossings(c)}")
        assert len(word) >= min_crossings(c)
    print("Lower bound holds.")

